#include <iostream>
#include <cmath>
using namespace std;

struct Point {
    double x, y;
};

double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

int main() {
    Point p0, p1, p2;
    int q;
    cin >> p0.x >> p0.y >> p1.x >> p1.y;
    cin >> q;
    while (q--) {
        cin >> p2.x >> p2.y;
        double cr = cross(p0, p1, p2);
        if (cr > 1e-9) {
            cout << "COUNTER_CLOCKWISE" << endl;
        } else if (cr < -1e-9) {
            cout << "CLOCKWISE" << endl;
        } else {
            // collinear
            double d = dot(p0, p1, p2);
            if (d < -1e-9) {
                cout << "ONLINE_BACK" << endl;
            } else {
                double len2 = (p1.x - p0.x) * (p1.x - p0.x) + (p1.y - p0.y) * (p1.y - p0.y);
                if (d > len2 + 1e-9) {
                    cout << "ONLINE_FRONT" << endl;
                } else {
                    cout << "ON_SEGMENT" << endl;
                }
            }
        }
    }
    return 0;
}

