    double normB = bx * bx + by * by;

    if (cross > EPS) {
        cout << "COUNTER_CLOCKWISE\n";
    } else if (cross < -EPS) {
        cout << "CLOCKWISE\n";
    } else if (dot < -EPS) {
        cout << "ONLINE_BACK\n";
    } else if (normA + EPS < normB) {
        cout << "ONLINE_FRONT\n";
    } else {
        cout << "ON_SEGMENT\n";
