public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int q = sc.nextInt();
        while (q-- > 0) {
            long x0 = sc.nextLong(), y0 = sc.nextLong();
            long x1 = sc.nextLong(), y1 = sc.nextLong();
            long x2 = sc.nextLong(), y2 = sc.nextLong();

            // vectors from p0
            long ax = x1 - x0, ay = y1 - y0;
            long bx = x2 - x0, by = y2 - y0;

            long cross = ax * by - ay * bx;

            if (cross > 0) {
                System.out.println("COUNTER_CLOCKWISE");
            } else if (cross < 0) {
                System.out.println("CLOCKWISE");
            } else {
                // collinear
                // dot product of a and b
                long dot = ax * bx + ay * by;
                // |a|^2
                long a2 = ax * ax + ay * ay;

                if (dot < 0) {
                    // p2 is behind p0 (ONLINE_BACK: order is p2, p0, p1)
                    System.out.println("ONLINE_BACK");
                } else if (dot > a2) {
                    // p2 is beyond p1 (ONLINE_FRONT: order is p0, p1, p2)
                    System.out.println("ONLINE_FRONT");
                } else {
                    // p2 is on segment p0p1
                    System.out.println("ON_SEGMENT");
                }
            }
        }
    }
}

