import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c > ' ' && c != -1 && c != '.') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c > ' ' && c != -1) {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static final double EPS = 1e-10;

    static Point sub(Point a, Point b) {
        return new Point(a.x - b.x, a.y - b.y);
    }

    static double cross(Point a, Point b) {
        return a.x * b.y - a.y * b.x;
    }

    static double dot(Point a, Point b) {
        return a.x * b.x + a.y * b.y;
    }

    static double norm(Point a) {
        return a.x * a.x + a.y * a.y;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        Point p0 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p1 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p2 = new Point(fs.nextDouble(), fs.nextDouble());

        Point a = sub(p1, p0);
        Point b = sub(p2, p0);

        double cr = cross(a, b);

        if (cr > EPS) {
            System.out.println("COUNTER_CLOCKWISE");
        } else if (cr < -EPS) {
            System.out.println("CLOCKWISE");
        } else if (dot(a, b) < -EPS) {
            System.out.println("ONLINE_BACK");
        } else if (norm(a) + EPS < norm(b)) {
            System.out.println("ONLINE_FRONT");
        } else {
            System.out.println("ON_SEGMENT");
        }
    }
}

