    return a.x * b.y - a.y * b.x;
}

long long dot(Point a, Point b) {
    return a.x * b.x + a.y * b.y;
}

Point sub(Point a, Point b) {
    Point r;
    r.x = a.x - b.x;
    r.y = a.y - b.y;
    return r;
}

int main(void) {
    Point p0, p1, p2;
    if (scanf("%lld %lld %lld %lld %lld %lld",
              &p0.x, &p0.y, &p1.x, &p1.y, &p2.x, &p2.y) != 6) {
        return 0;
    }

    Point a = sub(p1, p0);
    Point b = sub(p2, p0);

    long long cr = cross(a, b);

    if (cr > 0) {
        puts("COUNTER_CLOCKWISE");
    } else if (cr < 0) {
        puts("CLOCKWISE");
    } else {
        long long dt = dot(a, b);
        long long aa = dot(a, a);

        if (dt < 0) {
            puts("ONLINE_BACK");
        } else if (dt > aa) {
            puts("ONLINE_FRONT");
        } else {
            puts("ON_SEGMENT");
        }
    }

    return 0;
}

def solve():
